document.addEventListener("DOMContentLoaded",()=>{
  const q=id=>document.getElementById(id);if(!q("adminBundleFactoryPanel"))return;
  const state={assets:[],products:[],collections:[],selectedAssets:new Set(),compare:new Set(),filters:{query:"",status:"all",platform:"all",offer:"all"}};
  const toast=msg=>{const el=q("adminToast");if(el){el.hidden=false;el.textContent=msg;setTimeout(()=>el.hidden=true,3800)}};
  const activeAsset=()=>state.assets.find(x=>x.id===q("bundleFactoryAsset")?.value)||null;
  const selectedIds=()=>[...state.selectedAssets].filter(id=>state.assets.some(a=>a.id===id)).slice(0,6);
  const contentSummary=p=>Object.entries(p.bundle_config?.content||{}).filter(([,v])=>v).map(([k])=>k.toUpperCase()).join(" · ");
  const statusLabel=status=>({published:"IM SHOP",draft:"ENTWURF",archived:"ARCHIVIERT",mixed:"GEMISCHT"})[status]||String(status||"ENTWURF").toUpperCase();
  const money=(cents,currency="EUR")=>new Intl.NumberFormat("de-DE",{style:"currency",currency}).format(Math.max(0,Number(cents||0))/100);
  const catalogText=value=>String(value??"").toLocaleLowerCase("de-DE");
  function productMatchesCatalog(p,{useQuery=true,ignoreStatus=false}={}){const f=state.filters||{},query=catalogText(f.query).trim(),status=String(f.status||"all"),platform=String(f.platform||"all"),offer=String(f.offer||"all");if(!ignoreStatus&&status==="active"&&p.status==="archived")return false;if(!ignoreStatus&&!["all","active"].includes(status)&&p.status!==status)return false;if(platform!=="all"&&p.platform!==platform)return false;if(offer!=="all"&&p.offer_type!==offer)return false;if(!useQuery||!query)return true;const haystack=[p.title,p.description,p.collection_title,p.collection_key,p.platform,p.offer_type,p.version,p.design_variant,contentSummary(p),...(p.package_summary||[]).map(x=>x?.label||"")].map(catalogText).join(" ");return haystack.includes(query)}
  function collectionMembers(c){return state.products.filter(p=>p.collection_key===c.key)}
  function collectionMatchesCatalog(c){const query=catalogText(state.filters?.query).trim(),members=collectionMembers(c),status=String(state.filters?.status||"all");if(status==="active"&&c.status==="archived")return false;if(!["all","active"].includes(status)&&c.status!==status)return false;if(!members.some(p=>productMatchesCatalog(p,{useQuery:false,ignoreStatus:true}))&&members.length)return false;if(!query)return true;const haystack=[c.title,c.key,c.status,...members.flatMap(p=>[p.title,p.description,p.platform,p.offer_type,p.version,p.design_variant])].map(catalogText).join(" ");return haystack.includes(query)}
  const filteredProducts=()=>state.products.filter(p=>productMatchesCatalog(p));
  const filteredCollections=()=>state.collections.filter(c=>collectionMatchesCatalog(c));
  function renderCatalogControls(){const products=filteredProducts(),collections=filteredCollections(),archivedProducts=state.products.filter(p=>p.status==="archived").length,archivedCollections=state.collections.filter(c=>c.status==="archived").length;const set=(id,value)=>{const el=q(id);if(el)el.textContent=String(value)};set("adminCatalogProductCount",state.products.length);set("adminCatalogCollectionCount",state.collections.length);set("adminCatalogArchivedProductCount",archivedProducts);set("adminCatalogArchivedCollectionCount",archivedCollections);const summary=q("adminCatalogResultSummary");if(summary)summary.textContent=`${products.length} von ${state.products.length} Produkten · ${collections.length} von ${state.collections.length} Collections`;const archive=q("adminCatalogArchiveSummary");if(archive)archive.textContent=`${archivedCollections} archivierte Collections · ${archivedProducts} archivierte Produkte`;document.querySelectorAll("[data-catalog-quick]").forEach(btn=>btn.classList.toggle("active",btn.dataset.catalogQuick===(state.filters.status==="archived"?"archived":"all")))}
  function applyCatalogFilters(){renderCatalogControls();renderCollections();renderProducts()}
  const converterCatalog={
    stream_status:{label:"Stream-Status",details:{full:"KOMPLETT · START / PAUSE / ENDE / OFFLINE",starting:"STARTING SOON",pause:"PAUSE / BRB",ending:"STREAM ENDET",offline:"OFFLINE"}},
    overlays:{label:"Overlays",details:{branding:"BRANDING · KAMERA / SOCIAL / HEADER",frames:"STREAM-RAHMEN",status:"STATUS-SCREENS",full:"BRANDING + STATUS"}},
    panels:{label:"Panels / Cards",details:{starter:"STARTER SET"}},
    widgets:{label:"Provider-Widgets",details:{starter:"STARTER",alerts:"ALERTS",live:"LIVE / CHAT",goals:"GOALS"}},
    creator_pack:{label:"Creator-Pack",details:{full:"KOMPLETTER PACK",stream:"STREAM-PACK",branding:"BRANDING-PACK"}}
  };
  function converterAllowed(type,platform){if(!["twitch","tiktok","neutral"].includes(platform))return false;if(type==="panels"||type==="widgets")return ["twitch","tiktok"].includes(platform);return true}
  function converterDetailEntries(type,platform){const src={...(converterCatalog[type]?.details||{})};if(type==="widgets"){if(platform==="twitch"){delete src.goals}else if(platform==="tiktok"){delete src.live}else return []}return Object.entries(src)}
  function syncAdminConverter(){const type=q("adminConverterType")?.value||"stream_status",platformEl=q("adminConverterPlatform"),detailEl=q("adminConverterDetail");if(!platformEl||!detailEl)return;let platform=platformEl.value;if(!converterAllowed(type,platform)){platform=type==="panels"?"twitch":"twitch";platformEl.value=platform;toast(type==="panels"?"Panels/Cards sind derzeit für Twitch oder TikTok verfügbar.":"Provider-Widgets benötigen Twitch oder TikTok.")};const keep=detailEl.value,entries=converterDetailEntries(type,platform);detailEl.innerHTML=entries.map(([value,label])=>`<option value="${CFS.escape(value)}">${CFS.escape(label)}</option>`).join("");if(entries.some(([v])=>v===keep))detailEl.value=keep;const output=q("adminConverterOutput")?.value||"bundle_only",variants=q("adminConverterVariants")?.value||"1",preset=q("adminConverterPreset")?.value||"custom",count=selectedIds().length,detail=detailEl.options[detailEl.selectedIndex]?.text||"–";q("adminConverterSummary").textContent=`${converterCatalog[type]?.label||type} · ${platform.toUpperCase()} · ${detail} · ${preset.toUpperCase()} · ${output==="bundle_only"?"nur Bundle":output==="singles_only"?"nur Einzelstücke":"Bundle + Einzelstücke"} · ${variants} Variante${variants==="1"?"":"n"} · ${count} Bild${count===1?"":"er"}`;}

  function renderAssets(){
    const sel=q("bundleFactoryAsset"),keep=sel?.value;
    if(sel){sel.innerHTML=state.assets.map(a=>`<option value="${CFS.escape(a.id)}">${CFS.escape(a.name)} · ${CFS.escape(a.rights_status)}</option>`).join("");if(state.assets.some(a=>a.id===keep))sel.value=keep;}
    q("bundleFactoryAssets").innerHTML=state.assets.length?state.assets.map(a=>`<label class="bundle-asset-row ${state.selectedAssets.has(a.id)?"selected":""}"><input type="checkbox" data-asset-pick="${CFS.escape(a.id)}" ${state.selectedAssets.has(a.id)?"checked":""} ${a.shop_use_allowed?"":"disabled"}><img src="${CFS.escape(a.preview_url)}" alt=""><div><strong>${CFS.escape(a.name)}</strong><small class="${a.shop_use_allowed?"bundle-rights-ok":"bundle-rights-pending"}">${a.shop_use_allowed?"✓ SHOP-NUTZUNG FREIGEGEBEN":"RECHTE OFFEN"}</small></div></label>`).join(""):'<div class="admin-empty">Noch kein Bild hochgeladen.</div>';
    q("bundleFactoryAssets").querySelectorAll("[data-asset-pick]").forEach(el=>el.onchange=()=>{if(el.checked){if(state.selectedAssets.size>=6){el.checked=false;return toast("Maximal 6 Quellbilder pro Collection.")}state.selectedAssets.add(el.dataset.assetPick)}else state.selectedAssets.delete(el.dataset.assetPick);renderAssets();syncAdminConverter()});
    const a=activeAsset();if(a){q("bundleFactoryRights").value=a.rights_status;q("bundleFactoryRightsSource").value=a.rights_source||"";q("bundleFactoryRightsNote").value=a.rights_note||""}syncAdminConverter()
  }

  function versionHistory(p){const rows=Array.isArray(p.versions)?p.versions:[];if(!rows.length)return '<small class="bundle-version-empty">Noch keine Versionshistorie.</small>';return `<details class="bundle-version-history"><summary>${rows.length} VERSION${rows.length===1?"":"EN"}</summary>${rows.map(v=>`<div><b>v${CFS.escape(v.version)}</b><span>${CFS.escape(v.release_notes||"")}</span><small>${v.published_at?"VERÖFFENTLICHT":"ENTWURF"}</small></div>`).join("")}</details>`;}
  function commerceBox(p){
    if(p.offer_type!=="bundle")return `<div class="bundle-commerce-summary"><span>EINZELANGEBOT</span><b>${p.list_price_cents?CFS.escape(money(p.list_price_cents,p.currency)):"ohne Preis"}</b><small>${CFS.escape((p.sale_mode||"standalone_and_bundle").replaceAll("_"," ").toUpperCase())}</small></div>`;
    const offers=new Map((p.commerce_config?.item_offers||[]).map(x=>[`${x.kind}:${x.key}`,x]));
    const rows=(p.commerce_items||[]).map(item=>{const cfg=offers.get(`${item.kind}:${item.key}`)||{sale_mode:"bundle_only",price_cents:99};return `<div class="bundle-commerce-item" data-commerce-row data-kind="${CFS.escape(item.kind)}" data-key="${CFS.escape(item.key)}"><span>${CFS.escape(item.label)}</span><select data-commerce-mode><option value="bundle_only" ${cfg.sale_mode==="bundle_only"?"selected":""}>NUR BUNDLE</option><option value="standalone_and_bundle" ${cfg.sale_mode==="standalone_and_bundle"?"selected":""}>BUNDLE + EINZELN</option><option value="standalone_only" ${cfg.sale_mode==="standalone_only"?"selected":""}>NUR EINZELN</option></select><label><input type="number" min="0" max="99999" step="1" value="${Math.max(0,Number(cfg.price_cents||0))}" data-commerce-price> Cent</label></div>`}).join("");
    return `<details class="bundle-commerce-box"><summary>COMMERCE · BUNDLE + EINZELSTÜCKE</summary><div class="bundle-commerce-price"><label>BUNDLE-PREIS (CENT)<input type="number" min="0" max="999999" step="1" value="${Math.max(0,Number(p.list_price_cents||0))}" data-bundle-price="${CFS.escape(p.id)}"></label><small>${p.list_price_cents?`Geplant: ${CFS.escape(money(p.list_price_cents,p.currency))}`:"0 = Free/Beta-Modell beibehalten"}</small></div><div class="bundle-commerce-items">${rows}</div><button class="btn" data-commerce-save="${CFS.escape(p.id)}">ANGEBOTSSTRUKTUR SPEICHERN</button><small>Paid Preview bleibt ohne Checkout und ist bei deaktiviertem Commerce nicht installierbar.</small></details>`;
  }

  function coverMediaAssets(){return state.assets.filter(a=>a.shop_use_allowed&&a.rights_status==="approved"&&["image/png","image/webp"].includes(String(a.mime_type||"")))}
  function coverBox(p){
    const media=coverMediaAssets(),selected=String(p.cover_source_asset_id||""),options=media.map(a=>`<option value="${CFS.escape(a.id)}" ${a.id===selected?"selected":""}>${CFS.escape(a.name)} · ${CFS.escape(String(a.mime_type||"").replace("image/","").toUpperCase())}</option>`).join(""),mode=p.cover_mode==="media"?`MEDIEN-COVER · ${String(p.cover_mime||"").replace("image/","").toUpperCase()}`:"AUTO-SVG";
    return `<details class="bundle-cover-box"><summary>COVER · ${CFS.escape(mode)}</summary><div class="bundle-cover-controls"><label>PNG / WEBP AUS FREIGEGEBENER MEDIENBIBLIOTHEK<select data-cover-media-select="${CFS.escape(p.id)}" ${media.length?"":"disabled"}><option value="">${media.length?"Cover auswählen …":"Kein freigegebenes PNG/WebP vorhanden"}</option>${options}</select></label><div class="bundle-cover-actions"><button class="btn" data-cover-media-apply="${CFS.escape(p.id)}" ${media.length?"":"disabled"}>MEDIEN-COVER VERWENDEN</button><button class="btn" data-cover-svg-reset="${CFS.escape(p.id)}">AUTO-SVG WIEDERHERSTELLEN</button></div><small>Nur rechtegeprüfte PNG/WebP-Medien sind wählbar. JPG bleibt als Quellbild erlaubt, aber nicht als Shop-Cover. Bei Rechteentzug wird ein veröffentlichtes Produkt automatisch zum Entwurf.</small></div></details>`;
  }

  function productCard(p,compare=false){
    const cover=p.admin_cover_url||p.preview?.cover_url||p.preview?.asset_url||"",badge=`<span class="bundle-status ${CFS.escape(p.status||"draft")}">${CFS.escape(statusLabel(p.status))} · v${CFS.escape(p.version)}</span>`,offer=`<span class="bundle-offer-badge ${CFS.escape(p.offer_type||"bundle")}">${p.offer_type==="item"?"EINZELSTÜCK":"BUNDLE"}${p.list_price_cents?` · ${CFS.escape(money(p.list_price_cents,p.currency))}`:""}</span>`;
    return `<article class="bundle-product-card ${p.platform==="tiktok"?"tiktok":""} ${p.status==="archived"?"archived":""} ${p.offer_enabled===false?"disabled-offer":""}" data-product-card="${CFS.escape(p.id)}">${cover?`<div class="bundle-rendered-cover"><img src="${CFS.escape(cover)}" alt="${CFS.escape(p.title)} Cover"></div>`:""}<div class="bundle-product-copy"><small>${CFS.escape(p.collection_title||"COLLECTION")} · ${CFS.escape(String(p.design_variant||"").toUpperCase())}</small><strong>${CFS.escape(p.title)}</strong><div class="bundle-badges">${badge}${offer}</div><small>${CFS.escape(contentSummary(p)||p.package_summary?.map(x=>x.label).join(" · ")||"BRANDING")}</small>${compare?`<p>${CFS.escape(p.description||"")}</p><small>Release: ${CFS.escape(p.release_notes||"Initial release.")}</small>`:`<input data-product-title="${CFS.escape(p.id)}" maxlength="140" value="${CFS.escape(p.title)}"><textarea data-product-description="${CFS.escape(p.id)}" maxlength="1000" rows="3">${CFS.escape(p.description)}</textarea><select data-product-pricing="${CFS.escape(p.id)}"><option value="free" ${p.pricing_mode==="free"?"selected":""}>FREE</option><option value="beta" ${p.pricing_mode==="beta"?"selected":""}>BETA</option>${p.pricing_mode==="paid_preview"?'<option value="paid_preview" selected>PAID PREVIEW · VIA COMMERCE</option>':""}</select>${commerceBox(p)}${coverBox(p)}<div class="bundle-version-box"><label>RELEASE NOTES<textarea data-release-notes="${CFS.escape(p.id)}" maxlength="1200" rows="2" placeholder="Was ändert sich in dieser Version?"></textarea></label><div class="bundle-version-actions"><button class="btn" data-version-bump="patch" data-id="${CFS.escape(p.id)}">PATCH +1</button><button class="btn" data-version-bump="minor" data-id="${CFS.escape(p.id)}">MINOR +1</button></div>${versionHistory(p)}</div><div class="bundle-product-actions"><button class="btn" data-product-duplicate="${CFS.escape(p.id)}">PRODUKT DUPLIZIEREN</button><button class="btn" data-product-compare="${CFS.escape(p.id)}">${state.compare.has(p.id)?"AUS VERGLEICH":"VERGLEICHEN"}</button><button class="btn" data-product-save="${CFS.escape(p.id)}">SPEICHERN</button><a class="btn" href="${CFS.escape(p.detail_url)}" target="_blank" rel="noopener">SHOP-VORSCHAU</a>${p.status==="archived"||p.offer_enabled===false?'':`<button class="btn ${p.status==="published"?"":"primary"}" data-product-action="${p.status==="published"?"unpublish":"publish"}" data-id="${CFS.escape(p.id)}">${p.status==="published"?"AUS SHOP NEHMEN":"IM SHOP VERÖFFENTLICHEN"}</button>`}</div>`}</div></article>`;
  }

  function collectionCard(c){const action=c.status==="archived"?"restore":c.status==="published"?"unpublish":"publish",label=action==="restore"?"REAKTIVIEREN":action==="unpublish"?"GANZE COLLECTION AUS SHOP":"GANZE COLLECTION VERÖFFENTLICHEN";return `<article class="bundle-collection-card ${CFS.escape(c.status)}"><div><small>COLLECTION</small><strong>${CFS.escape(c.title)}</strong><span>${c.products} aktive Produkte · ${c.standalone||0} Einzelangebote · ${c.published} live · ${c.draft} Entwürfe</span></div><div class="bundle-collection-actions"><span class="bundle-status ${CFS.escape(c.status)}">${CFS.escape(statusLabel(c.status))}</span><button class="btn" data-collection-duplicate="${CFS.escape(c.key)}">COLLECTION DUPLIZIEREN</button><button class="btn ${action==="publish"?"primary":""}" data-collection-action="${action}" data-key="${CFS.escape(c.key)}">${label}</button>${c.status!=="archived"?`<button class="btn" data-collection-action="archive" data-key="${CFS.escape(c.key)}">COLLECTION ARCHIVIEREN</button>`:""}</div></article>`;}
  function renderCollections(){const wrap=q("bundleFactoryCollectionCards");if(!wrap)return;const rows=filteredCollections();wrap.innerHTML=rows.length?rows.map(collectionCard).join(""):`<div class="admin-empty">${state.collections.length?"Keine Collection passt zu Suche und Filtern.":"Noch keine Collection."}</div>`;wrap.querySelectorAll("[data-collection-action]").forEach(btn=>btn.onclick=()=>collectionAction(btn.dataset.key,btn.dataset.collectionAction));wrap.querySelectorAll("[data-collection-duplicate]").forEach(btn=>btn.onclick=()=>duplicateCollection(btn.dataset.collectionDuplicate));q("bundleFactoryCollections").textContent=state.collections.length?`${rows.length}/${state.collections.length} Collections · ${state.products.filter(p=>p.offer_enabled!==false&&p.status!=="archived").length} aktive Produkte`:"Noch keine Collection";}
  function renderProducts(){const rows=filteredProducts();q("bundleFactoryProducts").innerHTML=rows.length?rows.map(p=>productCard(p)).join(""):`<div class="admin-empty">${state.products.length?"Keine Produkte passen zu Suche und Filtern.":"Noch keine Produktentwürfe."}</div>`;const root=q("bundleFactoryProducts");root.querySelectorAll("[data-product-action]").forEach(btn=>btn.onclick=()=>productAction(btn.dataset.id,btn.dataset.productAction));root.querySelectorAll("[data-product-save]").forEach(btn=>btn.onclick=()=>saveProduct(btn.dataset.productSave));root.querySelectorAll("[data-product-compare]").forEach(btn=>btn.onclick=()=>toggleCompare(btn.dataset.productCompare));root.querySelectorAll("[data-product-duplicate]").forEach(btn=>btn.onclick=()=>duplicateProduct(btn.dataset.productDuplicate));root.querySelectorAll("[data-version-bump]").forEach(btn=>btn.onclick=()=>createVersion(btn.dataset.id,btn.dataset.versionBump));root.querySelectorAll("[data-commerce-save]").forEach(btn=>btn.onclick=()=>saveCommerce(btn.dataset.commerceSave));root.querySelectorAll("[data-cover-media-apply]").forEach(btn=>btn.onclick=()=>applyMediaCover(btn.dataset.coverMediaApply));root.querySelectorAll("[data-cover-svg-reset]").forEach(btn=>btn.onclick=()=>resetGeneratedCover(btn.dataset.coverSvgReset));renderCompare();}
  function renderCompare(){const chosen=state.products.filter(p=>state.compare.has(p.id)).slice(0,3),wrap=q("bundleFactoryCompare");wrap.hidden=!chosen.length;q("bundleFactoryCompareGrid").innerHTML=chosen.map(p=>productCard(p,true)).join("")}
  function render(){renderAssets();renderCatalogControls();renderCollections();renderProducts()}
  async function load(){try{const data=await CFS.json("/api/admin/store/bundle-factory");state.assets=data.assets||[];state.products=data.products||[];state.collections=data.collections||[];for(const id of [...state.selectedAssets])if(!state.assets.some(a=>a.id===id&&a.shop_use_allowed))state.selectedAssets.delete(id);render()}catch(e){toast(e.message)}}

  q("bundleFactoryAsset")?.addEventListener("change",renderAssets);
  q("bundleFactoryUpload")?.addEventListener("click",async()=>{const file=q("bundleFactoryFile")?.files?.[0];if(!file)return toast("Bitte zuerst ein PNG, JPG oder WebP auswählen.");try{const data=await CFS.json("/api/admin/store/bundle-assets",{method:"POST",headers:{"Content-Type":file.type||"application/octet-stream","X-CFS-File-Name":encodeURIComponent(file.name)},body:file});q("bundleFactoryFile").value="";if(data.asset?.shop_use_allowed)state.selectedAssets.add(data.asset.id);toast("Bild gespeichert. Rechte prüfen und freigeben.");await load()}catch(e){toast(e.message)}});
  q("bundleFactorySaveRights")?.addEventListener("click",async()=>{const a=activeAsset();if(!a)return toast("Bitte ein Bild auswählen.");const status=q("bundleFactoryRights").value;try{await CFS.json(`/api/admin/store/bundle-assets/${encodeURIComponent(a.id)}/rights`,{method:"PATCH",body:JSON.stringify({rights_status:status,shop_use_allowed:status==="approved",rights_source:q("bundleFactoryRightsSource").value,rights_note:q("bundleFactoryRightsNote").value})});if(status==="approved")state.selectedAssets.add(a.id);else state.selectedAssets.delete(a.id);toast(status==="approved"?"Shop-Nutzungsrechte freigegeben.":"Rechtestatus gespeichert.");await load()}catch(e){toast(e.message)}});
  ["adminConverterType","adminConverterPlatform","adminConverterDetail","adminConverterOutput","adminConverterVariants","adminConverterPreset","adminConverterBranding"].forEach(id=>q(id)?.addEventListener("change",syncAdminConverter));
  q("adminConverterGenerate")?.addEventListener("click",async()=>{const ids=selectedIds();if(!ids.length){const a=activeAsset();if(a?.shop_use_allowed)ids.push(a.id)}if(!ids.length)return toast("Markiere mindestens ein freigegebenes Quellbild.");const type=q("adminConverterType").value,platform=q("adminConverterPlatform").value;if(!converterAllowed(type,platform))return toast("Diese Produkt-/Plattform-Kombination ist nicht verfügbar.");try{const data=await CFS.json("/api/admin/store/converter/generate",{method:"POST",body:JSON.stringify({asset_ids:ids,product_type:type,platform,detail:q("adminConverterDetail").value,output_mode:q("adminConverterOutput").value,variant_count:Number(q("adminConverterVariants").value||1),style_preset:q("adminConverterPreset")?.value||"custom",include_branding:q("adminConverterBranding").checked,title:q("adminConverterTitle").value||undefined,collection_title:q("adminConverterCollection").value||undefined})});state.assets=data.assets||state.assets;state.products=data.products||[];state.collections=data.collections||[];const c=data.collection||{};toast(`Umgewandelt: ${c.parents||0} Bundle-Entwurf/Entwürfe · ${c.items||0} Einzelstücke.`);render();syncAdminConverter()}catch(e){toast(e.message)}});

  async function saveProduct(id){const root=q("bundleFactoryProducts"),title=root.querySelector(`[data-product-title="${CSS.escape(id)}"]`)?.value||"",description=root.querySelector(`[data-product-description="${CSS.escape(id)}"]`)?.value||"",select=root.querySelector(`[data-product-pricing="${CSS.escape(id)}"]`),pricing_mode=select?.value==="paid_preview"?undefined:select?.value||"free";try{await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}`,{method:"PATCH",body:JSON.stringify({title,description,...(pricing_mode?{pricing_mode}:{})})});toast("Produktentwurf gespeichert.");await load()}catch(e){toast(e.message)}}
  async function saveCommerce(id){const card=q("bundleFactoryProducts").querySelector(`[data-product-card="${CSS.escape(id)}"]`);if(!card)return;const items=[...card.querySelectorAll("[data-commerce-row]")].map(row=>({kind:row.dataset.kind,key:row.dataset.key,sale_mode:row.querySelector("[data-commerce-mode]")?.value||"bundle_only",price_cents:Number(row.querySelector("[data-commerce-price]")?.value||0)})),bundle_price_cents=Number(card.querySelector(`[data-bundle-price="${CSS.escape(id)}"]`)?.value||0);try{await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}/commerce`,{method:"PATCH",body:JSON.stringify({bundle_price_cents,items})});toast("Bundle-/Einzelangebotsstruktur gespeichert.");await load()}catch(e){toast(e.message)}}
  async function applyMediaCover(id){const card=q("bundleFactoryProducts").querySelector(`[data-product-card="${CSS.escape(id)}"]`),asset_id=card?.querySelector(`[data-cover-media-select="${CSS.escape(id)}"]`)?.value||"";if(!asset_id)return toast("Bitte ein freigegebenes PNG- oder WebP-Cover auswählen.");try{await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}/cover-media`,{method:"POST",body:JSON.stringify({asset_id})});toast("PNG/WebP-Cover gespeichert.");await load()}catch(e){toast(e.message)}}
  async function resetGeneratedCover(id){try{await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}/cover-generated`,{method:"POST",body:"{}"});toast("Automatisches SVG-Cover wiederhergestellt.");await load()}catch(e){toast(e.message)}}
  async function duplicateProduct(id){try{const data=await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}/duplicate`,{method:"POST",body:"{}"});toast(`Produkt dupliziert: ${data.product?.title||"neuer Entwurf"}`);await load()}catch(e){toast(e.message)}}
  async function duplicateCollection(key){try{const data=await CFS.json(`/api/admin/store/collections/${encodeURIComponent(key)}/duplicate`,{method:"POST",body:"{}"});toast(`Collection dupliziert: ${data.collection?.title||"neue Collection"}`);await load()}catch(e){toast(e.message)}}
  async function createVersion(id,bump){const notes=q("bundleFactoryProducts").querySelector(`[data-release-notes="${CSS.escape(id)}"]`)?.value?.trim()||"";if(!notes)return toast("Release Notes für die neue Version eintragen.");try{const data=await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}/version`,{method:"POST",body:JSON.stringify({bump,release_notes:notes})});toast(`Neue Produktversion v${data.product?.version||""} erstellt.`);await load()}catch(e){toast(e.message)}}
  function toggleCompare(id){if(state.compare.has(id))state.compare.delete(id);else{if(state.compare.size>=3)return toast("Maximal 3 Varianten gleichzeitig vergleichen.");state.compare.add(id)}renderProducts()}
  async function productAction(id,action){try{await CFS.json(`/api/admin/store/bundle-products/${encodeURIComponent(id)}/${action}`,{method:"POST",body:"{}"});toast(action==="publish"?"Produkt ist jetzt im Creator Shop.":"Produkt wurde aus dem Shop genommen.");await load()}catch(e){toast(e.message)}}
  async function collectionAction(key,action){try{const data=await CFS.json(`/api/admin/store/collections/${encodeURIComponent(key)}/${action}`,{method:"POST",body:"{}"});state.assets=data.assets||state.assets;state.products=data.products||[];state.collections=data.collections||[];toast(({publish:"Collection vollständig veröffentlicht.",unpublish:"Collection vollständig aus dem Shop genommen.",archive:"Collection archiviert.",restore:"Collection als Entwurf reaktiviert."})[action]||"Collection aktualisiert.");render()}catch(e){toast(e.message)}}
  q("adminCatalogSearch")?.addEventListener("input",event=>{state.filters.query=event.target.value||"";applyCatalogFilters()});
  q("adminCatalogStatus")?.addEventListener("change",event=>{state.filters.status=event.target.value||"all";applyCatalogFilters()});
  q("adminCatalogPlatform")?.addEventListener("change",event=>{state.filters.platform=event.target.value||"all";applyCatalogFilters()});
  q("adminCatalogOffer")?.addEventListener("change",event=>{state.filters.offer=event.target.value||"all";applyCatalogFilters()});
  q("adminCatalogReset")?.addEventListener("click",()=>{state.filters={query:"",status:"all",platform:"all",offer:"all"};if(q("adminCatalogSearch"))q("adminCatalogSearch").value="";if(q("adminCatalogStatus"))q("adminCatalogStatus").value="all";if(q("adminCatalogPlatform"))q("adminCatalogPlatform").value="all";if(q("adminCatalogOffer"))q("adminCatalogOffer").value="all";applyCatalogFilters()});
  document.querySelectorAll("[data-catalog-quick]").forEach(btn=>btn.addEventListener("click",()=>{state.filters.status=btn.dataset.catalogQuick==="archived"?"archived":"all";if(q("adminCatalogStatus"))q("adminCatalogStatus").value=state.filters.status;applyCatalogFilters()}));
  q("bundleFactoryClearCompare")?.addEventListener("click",()=>{state.compare.clear();renderProducts()});q("bundleFactoryRefresh")?.addEventListener("click",load);syncAdminConverter();load();
});
